occ={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# generate candidates: full squares and L subsets within 2x2
from itertools import combinations
cands=[]
for r in range(6):
 for c in range(6):
  block={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if block<=occ: cands.append(('S',block))
  for sub in combinations(sorted(block),3):
   if set(sub)<=occ: cands.append(('L',set(sub)))
sol=[]
def search(rem, chosen, nS):
 if not rem:
  if nS==1 and len(chosen)==5: sol.append(chosen[:])
  return
 if len(chosen)>=5: return
 p=min(rem)
 for typ,shape in cands:
  if p in shape and shape<=rem and (typ!='S' or nS<1):
   search(rem-shape,chosen+[(typ,shape)],nS+(typ=='S'))
search(occ,[],0)
len(sol)
